"""Planet-in-house effects and dasha lines, eight languages."""
from __future__ import annotations

L = ("hi", "mr", "gu", "bn", "ta", "te", "kn", "ml")

def T(hi, mr, gu, bn, ta, te, kn, ml):
    return dict(zip(L, (hi, mr, gu, bn, ta, te, kn, ml)))

def _pack(rows):
    """rows: list of (english, eight-tuple)."""
    return {en: T(*eight) for en, eight in rows}

